--
-- Name: current_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    raw TEXT;
    tid UUID;
BEGIN
    raw := current_setting('app.tenant_id', true);
    IF raw IS NULL OR raw = '' THEN
        RETURN NULL;
    END IF;
    BEGIN
        tid := raw::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
    RETURN tid;
END;
$$;


--
-- Name: current_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    raw TEXT;
    uid UUID;
BEGIN
    raw := current_setting('app.user_id', true);
    IF raw IS NULL OR raw = '' THEN
        RETURN NULL;
    END IF;
    BEGIN
        uid := raw::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
    RETURN uid;
END;
$$;


--
-- Name: prevent_archived_dict_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_archived_dict_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM erp.dict_types dt
        WHERE dt.id = NEW.type_id
        AND dt.status = 'archived'
    ) THEN
        RAISE EXCEPTION 'Cannot modify archived dictionary items. HR dictionary data is managed by HRM service.';
    END IF;
    
    IF EXISTS (
        SELECT 1 FROM erp.archive_marks am
        WHERE am.schema_name = 'erp'
        AND am.table_name = 'dict_types'
        AND am.archive_type = 'row'
        AND am.column_name = NEW.id::text
    ) THEN
        RAISE EXCEPTION 'Cannot modify archived dictionary types. HR dictionary data is managed by HRM service.';
    END IF;
    
    RETURN NEW;
END;
$$;


