--
-- Name: report_stats; Type: VIEW; Schema: bi; Owner: -
--

CREATE VIEW bi.report_stats AS
 SELECT report_type,
    status,
    count(*) AS count,
    count(
        CASE
            WHEN (last_generated_at > (CURRENT_TIMESTAMP - '24:00:00'::interval)) THEN 1
            ELSE NULL::integer
        END) AS recently_generated
   FROM bi.reports
  WHERE (is_active = true)
  GROUP BY report_type, status;


