--
-- Name: email_stats; Type: VIEW; Schema: mail; Owner: -
--

CREATE VIEW mail.email_stats AS
 SELECT status,
    count(*) AS count,
    avg(
        CASE
            WHEN (sent_at IS NOT NULL) THEN EXTRACT(epoch FROM (sent_at - created_at))
            ELSE NULL::numeric
        END) AS avg_send_time_seconds
   FROM mail.emails
  GROUP BY status;


