--
-- Name: assets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.assets AS
 SELECT id,
    organization_id,
    asset_number,
    name,
    category,
    brand,
    model,
    purchase_date,
    purchase_amount,
    location,
    responsible_id,
    status,
    serial_number,
    manufacturer,
    rated_power,
    rated_voltage,
    rated_current,
    specifications,
    image_url,
    department,
    created_at,
    updated_at,
    deleted_at,
    tenant_id,
    company_id,
    asset_code,
    purchase_price,
    current_value,
    department_id,
    employee_id,
    description
   FROM erp.assets;


