CREATE TABLE qms.inspection_items (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    organization_id uuid NOT NULL,
    inspection_id uuid NOT NULL,
    item_number integer,
    item_name character varying(255) NOT NULL,
    item_category character varying(50),
    specification text,
    requirement text,
    test_method character varying(100),
    expected_value character varying(255),
    actual_value character varying(255),
    tolerance character varying(100),
    unit character varying(50),
    is_critical boolean DEFAULT false,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    result character varying(20),
    deviation text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    deleted_at timestamp with time zone,
    tenant_id uuid,
    CONSTRAINT ck_inspection_items_status_standard CHECK (((status IS NULL) OR ((status)::text = ANY ((ARRAY['active'::character varying, 'inactive'::character varying, 'archived'::character varying])::text[]))))
);

ALTER TABLE ONLY qms.inspection_items FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE inspection_items; Type: COMMENT; Schema: qms; Owner: -
--

COMMENT ON TABLE qms.inspection_items IS '检验项明细表';


